// Extract the tracking data passed by the agent.
// Expected input: { confession: string, date?: string, tags?: string[] }
const input = $input.first().json;
const confession = input.confession ?? '(no content provided)';
const date = input.date ?? new Date().toISOString().split('T')[0];
const tags = Array.isArray(input.tags) ? input.tags : [];

// Format as an Obsidian note in markdown
const tagLine = tags.length > 0 ? `\ntags: [${tags.map(t => `'${t}'`).join(', ')}]` : '';
const noteContent = `---
date: ${date}
type: tracking-confession${tagLine}
created_by: EverythingApp Agent
---

# Tracking Confession — ${date}

${confession}
`;

return [{ json: { noteContent, date, fileName: `Tracking Confession ${date}.md` } }];
